 t=p.read_text(); q=re.search(r'Elapsed \(wall clock\) time .*: ([0-9:]+\.[0-9]+)',t).group(1).split(':'); wall=sum(float(x)*60**(len(q)-i-1) for i,x in enumerate(q)); return {'wall_seconds':wall,'peak_rss_kib':int(re.search(r'Maximum resident set size \(kbytes\): (\d+)',t).group(1)),'swaps':int(re.search(r'Swaps: (\d+)',t).group(1)),'exit_status':int(re.search(r'Exit status: (\d+)',t).group(1)),'sha256':sha(p)}
