 d=j(p/'docker-inspect.json')[0];h=d['HostConfig'];st=d['State'];sl=j(p/'reservation-before.json')['slice'];ok=h['MemoryReservation']==5368709120 and h['Memory']==7516192768 and h['MemorySwap']==7516192768 and h['PidsLimit']==128 and h['NetworkMode']=='none' and h['CgroupParent']=='aspisr425.slice' and all(x in sl for x in ('MemoryHigh=5368709120','MemoryMax=7516192768','MemorySwapMax=0','TasksMax=128')) and st['ExitCode']==({'v1 failed build':1,'v2 successful build':0,'8-check execution':0}[label]) and not st['OOMKilled'];ck(label+' capped status',ok,{'container_exit':st['ExitCode'],'oom':st['OOMKilled'],'caps':{k:h[k] for k in ('MemoryReservation','Memory','MemorySwap','PidsLimit','NetworkMode','CgroupParent')},'systemd_slice':sl})
